Menjalankan kode berbeda tergantung kondisi:

```js
let nilai = 75;

if (nilai >= 90) {
  console.log('A');
} else if (nilai >= 70) {
  console.log('B');
} else {
  console.log('C');
}

// Switch
let hari = 'senin';
switch (hari) {
  case 'senin':
    console.log('Kerja');
    break;
  case 'minggu':
    console.log('Libur');
    break;
  default:
    console.log('Hari lain');
}
```

Mengulang kode beberapa kali:

```js
// for
for (let i = 0; i < 3; i++) {
  console.log(i); // 0, 1, 2
}

// while
let n = 0;
while (n < 3) {
  console.log(n);
  n++;
}

// for...of (untuk array)
let buah = ['apel', 'jeruk'];
for (let b of buah) {
  console.log(b);
}
```

Hati-hati infinite loop: pastikan kondisi berhenti tercapai.

Fungsi membungkus logika agar bisa dipakai ulang:

```js
function sapa(nama) {
  return 'Halo, ' + nama + '!';
}

sapa('Budi'); // 'Halo, Budi!'

// Arrow function (modern)
const kali = (a, b) => a * b;
kali(3, 4); // 12

// Default parameter
function diskon(harga, persen = 10) {
  return harga - harga * persen / 100;
}
```

Fungsi bisa menjadi nilai: `const fn = sapa; fn('Ani');`

DOM (Document Object Model) adalah representasi HTML sebagai objek JS:

```js
// Ambil elemen
const btn = document.querySelector('#tombol');
const teks = document.querySelector('.judul');

// Ubah konten & style
teks.textContent = 'Judul Baru';
teks.style.color = 'red';

// Respon event
btn.addEventListener('click', () => {
  alert('Tombol diklik!');
});

// Buat elemen baru
const p = document.createElement('p');
p.textContent = 'Paragraf baru';
document.body.appendChild(p);
```
